(() => {
  window.__etnFooterMetrics = () => {
    const root = document.querySelector('.ui-comment');
    if (root === null) return null;
    const zone = root.parentElement;
    const field = root.querySelector('.md-field--editing');
    const footer = field === null ? null : field.querySelector(':scope > .md-field-actions');
    if (zone === null || field === null || footer === null) return null;
    const z = zone.getBoundingClientRect();
    const f = footer.getBoundingClientRect();
    const fld = field.getBoundingClientRect();
    const area = field.querySelector(':scope > .md-field-area');
    const a = area === null ? null : area.getBoundingClientRect();
    return {
      zoneDisplay: getComputedStyle(zone).display,
      zoneOverflow: getComputedStyle(zone).overflowY,
      rootHeight: Math.round(root.getBoundingClientRect().height),
      zoneContentHeight: Math.round(z.height - 16),
      zoneHeight: Math.round(z.height),
      fieldHeight: Math.round(fld.height),
      areaHeight: a === null ? null : Math.round(a.height),
      footerPosition: getComputedStyle(footer).position,
      footerBottomGap: Math.round(z.bottom - f.bottom),
      footerUnderText: a !== null && a.bottom <= f.top + 1,
    };
  };
  return true;
})()
